INSERT INTO `food` VALUES (1,'西湖醋鱼','杭州传统名菜，属于浙菜系。鱼肉鲜嫩，酸甜可口。','草鱼、醋、糖、酱油、料酒、姜、葱','1.将草鱼宰杀洗净\n2.在鱼身上划几刀\n3.水烧开后放入鱼煮熟\n4.捞出装盘\n5.用原汤加醋、糖、酱油等调料勾芡\n6.浇在鱼身上即可','相传南宋时，宋嫂为生病的丈夫烹制此菜，后流传成为杭州名菜',20,'西湖区',NULL,NULL,NULL,1,0,'2026-04-02 17:47:44','2026-04-02 17:47:44','',NULL),(2,'北京烤鸭','北京著名特色菜肴，色泽红润，肉质肥而不腻','北京填鸭、甜面酱、葱丝、黄瓜丝、荷叶饼','1.选用优质北京填鸭\n2.经过充气、烫皮、挂糖色、晾胚等工序\n3.用果木炭火烤制\n4.片成薄片\n5.配以甜面酱、葱丝、黄瓜丝和荷叶饼食用','北京烤鸭起源于南北朝时期，当时称为炙鸭，到明朝成为宫廷名菜，后传入民间',1,'北京市',NULL,NULL,NULL,1,0,'2026-04-02 17:49:42','2026-04-02 17:49:42','',NULL),(12,'喜茶-HEYTEA','代表产品包括：多肉葡萄家族、酷黑莓桑、超级植物茶、芝芝莓莓、多肉桃李、满杯红柚、烤黑糖波波牛乳、喜柿多多、芋泥牛乳满贯、芋糯糯等产品。','','','2011年12月，首杯芝士现泡茶Beta版——奶盐绿茶面世。\r\n2012年5月，第一家喜茶店在广东省江门市江边里的一条小巷内开业，那时候它还叫“皇茶 ROYALTEA”\r\n2016年2月26日，全面升级为注册品牌“喜茶HEYTEA” [83]；7月，喜茶首创「满杯红柚」，同期推出满杯水果茶系列；\r\n2017年2月，「芝芝莓莓」首登场，芝芝系列开启，3 月、6 月分别推出「芝芝芒芒」和「芝芝桃桃」；\r\n2018年4月25日，新式茶饮品牌“喜茶”宣布完成4亿元人民币B轮融资，由美团点评旗下产业基金龙珠资本投资；;6月，推出喜茶GO微信小程序。\r\n2018年11月，喜茶开始布局海外市场，首家海外门店在新加坡ION Orchard开业 [157];12月，香港首店正式营业； [83]\r\n2020年，创立全新子品牌喜小茶 [158]。\r\n2020年6月，推出喜茶瓶装饮料业务，喜茶气泡水上市；8月，上线「生打椰椰」系列饮品，首次把「生打椰」引入行业；12月，澳门首店威尼斯人店开业。\r\n2021年6月，喜茶瓶装果汁茶上市，开启瓶装灵感新征程；7月13日，喜茶刚刚交割完毕新一轮5亿美元的融资；8月，「多肉青提」诞生，继多肉葡萄候现象级TOP产品；11月，喜茶会员体系改版；12月，推出定制字体“喜茶灵感体”；\r\n2022年2月，喜茶宣布告别30元，不再推出高于29元的产品，承诺现有产品在2022年内绝不涨价；11月，喜茶的平价子品牌喜小茶已关闭全部门店 [105];11月，喜茶开放加盟，新茶饮卷向下沉市场 [108];11月，喜茶开放事业合伙业务，服务更多大众用户 [114];\r\n2023年1月，入选2022年胡润中国500强 [109]；3月，喜茶宣布全新的品牌slogan“喜悦发生” [115];4月，喜茶联合11个城市文旅部门推出城市文旅限定冰箱贴 [116];7月27日，喜茶宣布目前门店总数已突破2000店，进入超240个城市，喜茶GO会员数达到8000万 [122];8月4日，喜茶宣布英国首店开业，喜茶在全球各地门店已超过2000店 [123];9月21日，喜茶在南京市红山森林动物园举办公益认养仪式，宣布认养水豚“杏仁” [132];10月，在澳大利亚墨尔本、加拿大本拿比开设两个国家市场的各自首店 [159]；10月26日，喜茶宣布将公开产品配方原料，为消费者提供“真品质”新茶饮产品 [135];12月8日，喜茶纽约百老汇店正式投入营运，正式开启其在美国市场的发展。 [138]\r\n2024年6月，喜茶在巴黎11区RUE BRéGUET打造快闪门店喜茶巴黎观赛茶室 [144];7月5日，喜茶于法国巴黎打造的快闪门店“喜茶巴黎观赛茶室”正式开业 [145];7月，喜茶英国伦敦New Oxford St店正式开业 [146]：8月15日，喜茶在行业内率先公开在售现制饮品的咖啡因含量，并参考咖啡因人体代谢的相关研究成果及对睡眠可能的影响，开创性使用了“咖啡因红绿灯”健康标识，对产品咖啡因含量进行分级公示 [148]：9月18日，澎湃新闻记者获悉，喜茶向事业合伙人发布了主题为《为用户创造差异化的品牌和产品》的内部信。喜茶在该内部信中指出，当前行业陷入了同质化竞争，持续消耗着用户对茶饮产品和品牌的热情。喜茶表示，接下来拒绝惯性的同质化思维、不做单纯的低价内卷，将推出更多差异化的产品和品牌活动 [150]。11月4日，喜茶在中国标准化研究院专业技术指导下发布行业首个“新茶饮健康标识体系”，对茶饮产品面向消费者公开产品信息做出了全面的规范 [153]：12月19日，喜茶向事业合伙人发布了主题为《更好落地差异化 把握新年新机遇》的第四季度公开信，提出在2025年将推出全新的优秀合伙人激励政策和门店发展政策，支持合伙人继续提升门店品质与用户体验，并设立了总额达5000万元的合伙人门店形象升级、选址优化激励基金。 [155]\r\n2025年1月2日，喜茶发布2024年度报告，会员数超1.5亿。 [160]：1月17日，喜茶最新DP店成都春熙路店“叠院”正式开业 [161]：2月10日，记者获悉喜茶发出名为《不参与数字游戏与规模内卷，回归用户与品牌》的内部全员邮件。喜茶在邮件中表示，拒绝门店规模内卷，暂时停止接受事业合伙申请 [162]。2月23日，喜茶首家海外LAB店在美国纽约时代广场开业。 [163]3月17日消息，喜茶位于日本大阪道顿堀的首店已开业。 [164]5月13日，喜茶在迎来品牌13周年之际，全国限时上新江门江边里创始店的限定饮品「江边里·芝芝柑普」 [191]；5月20日，喜茶携手深圳南山区、广州越秀区、杭州上城区、成都锦江区和武汉武昌区5座城市的民政局,为新人解锁领证专属浪漫。 [188]5月26日，「爆汁杨梅」、「轻芝杨梅」及「芝芝多肉杨梅」三款产品上新 [192]。6月12日，喜茶上新时令新品“奇香黄皮桃”，时隔四年带来黄皮系列的差异化研发创新。 [195]6月23日，喜茶推出第三款藏地灵感新品“牦牛乳酥油茶”，再次焕新高原传统茶文化。 [197]7月，喜茶北京朝阳大悦城店迎来空间升级后的焕新亮相，以青石为枰、茶器作子，打造一间“棋上茶室”，成为喜茶落地全新空间设计，探索灵感茶禅的最新呈现。 [200]8月4日报道，喜茶开进苹果总部所在地库比蒂诺，海外门店超100家，美国超30家门店。已建立起覆盖全业务链条的海外营运体系，并率先在美国上线自营外卖系统。 [201]8月，喜茶官宣了与《CHIIKAWA》的联名合作。 [204]8月22日，喜茶全国超4000家门店全量上线淘宝闪购（饿了么）。 [205-206]9月19日，喜茶超级植物茶迎来上新一周年，据官方数据显示，超级植物茶全系列产品已售出超1亿杯。 [207]据极海品牌监测数据，截至2025年10月，喜茶门店总数为3930家，与去年同期相比净减少680家。另据窄门餐眼统计，截至发稿，喜茶门店数进一步降至3883家。对此，喜茶相关负责人表示“不予置评”。 [212] [214]\r\n2026年1月13日，焕新升级后的喜茶香港K11 ART MALL门店,迎来了与灵感好友Twins共创的香港限定茶特调「黑松露炒蛋英红」。 [221]1月23日，新茶饮企业喜茶发布2025年度“小事记”显示，2025年喜茶批量重装130多家门店，已在海外32个城市开出了100多家门店 [215]。2月6日，喜茶DP计划（HEYTEA DAY DREAMER PROJECT，白日梦计划）系列新作广州沙面DP店正式开业，同日，喜茶广州乐峰广场店与广州广百新一城店也一齐亮相 [216]。2月25日消息，喜茶位于加拿大多伦多伊顿中心的heytealab门店正式开业。 [218]heytea lab聚焦茶饮风味与呈现方式的探索，推出了包括“岩兰鱼子酱”“岩兰2”“岩兰3”“岩兰冷萃”等创新茶饮在内的8款全球独家限定新品。除此以外，消费者可以在店内看到不同茶叶和植物原料，萃取茶叶的研发器具等。 [219]\r\n2026年2月28日，喜茶上海丰盛里lab店正式开业，heytea lab 2.0全国首店亮相。 [220]',274,'江门市','/uploads/foods/7834eef8-ed5b-42eb-9541-5fb66d17fb35_6022007359be480.jpg_e1080.webp',11,'dusk',1,0,'2026-04-06 21:44:59','2026-04-06 21:45:11','甜',NULL),(37,'广式虾饺','晶莹透亮的水晶皮裹着整只鲜虾，一口爆汁，Q弹爽滑，是广州早茶\"四大天王\"之首。','澄面、鲜虾仁、猪肥膘、笋丁','澄面烫熟揉团擀成薄皮，包入鲜虾馅，旺火蒸制5分钟至皮透馅熟。','虾饺起源于20世纪初广州的伍凤居茶楼，因形似月牙、皮薄如纸而闻名，如今已是广式早茶的代表点心。',268,'广州市','/uploads/foods/hargow.jpg',12,'美食达人阿强',1,128,'2026-11-06 18:50:10','2026-11-07 18:50:10','鲜,爽滑,弹牙','粤菜'),(38,'广式烧鹅','外皮金黄酥脆，鹅肉鲜嫩多汁，蘸上秘制酸梅酱，肥而不腻，皮脆肉香。','清远黑鬃鹅、五香粉、麦芽糖、米酒','整鹅开膛腌制入味，充气后浇皮水风干，挂炉明火烤制至表皮枣红酥脆。','烧鹅源于新会古井，以明火挂炉古法烧制，与北京烤鸭齐名，是粤菜烧腊的灵魂。',284,'东莞市','/uploads/foods/roastgoose.jpg',13,'寻味陈师傅',1,96,'2026-11-05 18:50:10','2026-11-07 18:50:10','酥脆,咸香,肥美','粤菜'),(39,'潮汕牛肉火锅','现切黄牛肉片入滚烫牛骨清汤一涮即熟，鲜嫩回甘，蘸沙茶酱最是地道。','本地黄牛、牛骨、白萝卜、沙茶酱','牛骨熬制清汤打底，牛肉手工现切，按部位涮煮至断生即食。','潮汕牛肉火锅讲究\"鲜\"字，从宰杀到上桌不超4小时，成就了\"没有一只牛能活着走出潮汕\"的传说。',272,'汕头市','/uploads/foods/beefhotpot.jpg',14,'舌尖小记',1,145,'2026-11-04 18:50:10','2026-11-07 18:50:10','鲜嫩,清甜','火锅'),(40,'顺德双皮奶','上层奶皮浓郁、下层奶冻滑嫩，入口即化，奶香四溢，是顺德甜品的一张名片。','水牛奶、鸡蛋清、白砂糖','水牛奶煮沸冷却结皮，倒出奶液与蛋清糖拌匀，重新灌回碗中蒸熟成冻。','双皮奶起源于顺德大良，已有百余年历史，因凝固后有两层奶皮而得名，是岭南糖水的经典。',529,'顺德区','/uploads/foods/shuangpinai.jpg',12,'美食达人阿强',1,88,'2026-11-03 18:50:10','2026-11-07 18:50:10','嫩滑,清甜,奶香','甜品'),(41,'北京烤鸭','皮脆肉嫩、色泽红润，配京葱黄瓜甜面酱卷荷叶饼，一口下去层次分明，肥而不腻。','填鸭、麦芽糖、荷叶饼、京葱、甜面酱','填鸭灌汤充气挂糖晾皮，果木挂炉烤制，片成108片皮肉相间。','北京烤鸭始于明朝，明清两代成为宫廷名菜，如今是享誉中外的中国国宴名馔。',1,'北京市','/uploads/foods/pekingduck.jpg',13,'寻味陈师傅',1,210,'2026-11-02 18:50:10','2026-11-07 18:50:10','酥脆,香嫩,肥而不腻','京菜'),(42,'四川火锅','红油翻滚、麻辣鲜香，毛肚黄喉入锅七上八下，吃得酣畅淋漓，是川渝人的集体记忆。','牛油、郫县豆瓣、花椒、朝天椒、毛肚、黄喉','牛油熬化下豆瓣香料炒制锅底，加高汤煮沸，涮煮各色食材。','川渝火锅源于长江码头船工，以麻辣鲜香著称，一口红锅征服大江南北。',334,'成都市','/uploads/foods/sichuanhotpot.jpg',14,'舌尖小记',1,182,'2026-11-01 18:50:10','2026-11-07 18:50:10','麻辣,鲜香','火锅'),(43,'麻婆豆腐','豆腐嫩滑如脂，配川式红油豆瓣与牛肉末，麻辣烫香酥嫩鲜浑为一体，下饭一绝。','嫩豆腐、牛肉末、郫县豆瓣、花椒粉、蒜苗','豆腐焯水后与牛肉末、豆瓣同烧，勾芡收汁，撒花椒粉蒜苗出锅。','麻婆豆腐创于清同治年间成都\"陈麻婆\"饭铺，以\"麻、辣、烫、香、酥、嫩、鲜、活\"八字闻名。',334,'成都市','/uploads/foods/mapotofu.jpg',12,'美食达人阿强',1,156,'2026-10-31 18:50:10','2026-11-07 18:50:10','麻辣,鲜香,嫩滑','川菜'),(44,'长沙臭豆腐','外焦里嫩、闻着臭吃着香，浇上秘制辣椒酱和萝卜干，一口一个停不下来。','黄豆、卤水、辣椒酱、萝卜干、蒜蓉','豆腐经特制卤水发酵，入油锅炸至外酥里嫩，浇料汁即食。','长沙臭豆腐又称\"臭干子\"，是湘菜小吃代表，\"闻起来臭、吃起来香\"蜚声全国。',254,'长沙市','/uploads/foods/stinkytofu.jpg',13,'寻味陈师傅',1,135,'2026-10-30 18:50:10','2026-11-08 12:22:51','外焦里嫩,香辣','湘菜'),(45,'西安羊肉泡馍','馍块筋道、羊肉醇香，浓汤久煮入味，配糖蒜辣酱，是西安人清晨的仪式感。','羊肉、定心馍、木耳、粉丝、花椒','馍掰成黄豆大小，与羊肉羊汤同煮，加粉丝木耳熬至软糯入味。','羊肉泡馍古称\"羊羹\"，源于西周，苏轼有\"陇馔有熊腊，秦烹唯羊羹\"之句，是西安最具代表性的美食。',387,'西安市','/uploads/foods/paomo.jpg',14,'舌尖小记',1,102,'2026-10-29 18:50:10','2026-11-07 18:50:10','鲜香,醇厚','陕菜'),(46,'杭州东坡肉','色泽红亮、皮糯肉酥，肥而不腻，甜中带咸，入口即化，是杭帮菜的头牌。','五花肉、黄酒、酱油、冰糖、葱姜','五花肉切块焯水，加黄酒冰糖慢火焖煮至酥烂，收汁红亮。','东坡肉为宋代苏轼所创，其在杭州任上治水有功，百姓以猪肉相赠，东坡烹制回赠，遂成佳话。',158,'杭州市','/uploads/foods/dongporou.jpg',12,'美食达人阿强',1,118,'2026-10-28 18:50:10','2026-11-07 18:50:10','软糯,肥而不腻,酱香','浙菜'),(47,'1','1','1','1','1',494,'花都区',NULL,11,'dusk',1,0,'2026-11-08 10:57:01','2026-11-08 10:57:01','酸\\涩\\烟熏味\\回甘','主食'),(48,'1312321','3123123','312312','2321312','123123',494,'花都区',NULL,11,'dusk',1,0,'2026-11-08 11:03:36','2026-11-08 11:03:36','酸\\涩\\烟熏味\\回甘','饮品'),(50,'测试美食112846','测试描述','测试食材','测试做法','测试历史',494,'花都区',NULL,15,'t112846',1,2,'2026-11-08 11:28:46','2026-11-08 11:32:43','酸\\甜','主食'),(51,'测试美食113305','测试描述','测试食材','测试做法','测试历史',494,'花都区',NULL,16,'t113305',1,1,'2026-11-08 11:33:05','2026-11-08 11:33:05','酸\\甜','主食');
/*!40000 ALTER TABLE `food` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `food_favorite`
--

DROP TABLE IF EXISTS `food_favorite`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `food_favorite` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
